function drawShapeEquation(g: Gsel, cx: number, cy: number, equation: string): void {
  lbl(g, cx, cy + ROW_EQ_GAP, equation, { size: 12, color: COLORS.muted, font: 'monospace' });
}

function drawMatmulRow(
  g: Gsel,
  cx: number,
  cy: number,
  leftLabel: string,
  leftShape: string,
  leftFill: string,
  leftStroke: string,
  weightLabel: string,
  weightShape: string,
  weightFill: string,
  weightStroke: string,
  rightLabel: string,
  rightShape: string,
  rightFill: string,
  rightStroke: string,
  equation: string
): number {
  // Input vector, weight matrix, operator circle, and output vector are spaced
  // so the circle sits cleanly between the weight and the output.
  const leftX = cx - 220;
  const weightX = cx - 40;
  const opX = cx + 130;
  const rightX = cx + 160;
  const outVecW = 120;

  drawSmallVector(g, leftX, cy, leftLabel, leftShape, leftFill, leftStroke);
  drawWeightMatrix(g, weightX, cy, weightLabel, weightShape, weightFill, weightStroke);
  drawSmallVector(g, rightX, cy, rightLabel, rightShape, rightFill, rightStroke, outVecW);

  g.append('circle').attr('cx', opX).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, cy, '@', { size: 13, weight: '700', color: '#64748b' });

  arrowH(g, leftX + VEC_W, opX - 14, cy, leftStroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, cy, weightStroke);
  arrowH(g, opX + 14, rightX, cy, rightStroke);

  drawShapeEquation(g, cx, cy, equation);
  return cy + MAT_H / 2 + ROW_EQ_GAP + 12;
}

function drawParamSummary(
  g: Gsel,
  cx: number,
  y: number,
  dModel: number,
  dFf: number,
  nExperts: number,
  topK: number,
  sharedExperts: number,
  routing: string,
  expertType: string
): number {
  const SUM_W = 1260;
  const SUM_H = 78;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect').attr('width', SUM_W).attr('height', SUM_H).attr('rx', 8)
    .attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 1);
  lbl(grp, 18, 22, 'Parameters →', { size: 11, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model=${dModel}`, dim: 'hidden dim', color: '#4caf50' },
    { label: `d_ff=${dFf}`, dim: 'FFN inner', color: '#1976d2' },
    { label: `E=${nExperts}`, dim: 'routed experts', color: '#7c3aed' },
    { label: `k=${topK}`, dim: 'selected', color: '#d81b60' },
    { label: routing.replace(/-/g, ' '), dim: 'routing', color: '#009688' },
    { label: expertType.replace(/-/g, ' '), dim: 'expert type', color: '#f57c00' },
  ];
  const itemW = 178;
  const startX = 18;
  items.forEach((item, i) => {
    const px = startX + i * itemW;
    grp.append('rect').attr('x', px).attr('y', 30).attr('width', itemW - 6).attr('height', 38).attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08)).attr('stroke', item.color).attr('stroke-width', 1);
    lbl(grp, px + 9, 49, item.label, { size: 11, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 9, 63, `→ ${item.dim}`, { size: 9, color: item.color, anchor: 'start' });
  });

  if (sharedExperts > 0) {
    const sharedColor = '#00838f';
    const px = startX + items.length * itemW;
    grp.append('rect').attr('x', px).attr('y', 30).attr('width', itemW - 6).attr('height', 38).attr('rx', 6)
      .attr('fill', hexWithAlpha(sharedColor, 0.08)).attr('stroke', sharedColor).attr('stroke-width', 1);
    lbl(grp, px + 9, 49, `shared=${sharedExperts}`, { size: 11, weight: '600', color: sharedColor, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 9, 63, '→ always active', { size: 9, color: sharedColor, anchor: 'start' });
  }

  return y + SUM_H + 16;
}

