function drawTopKMatrix(
  g: Gsel,
  cx: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  selectedPerRow: number,
  transpose = false
): number {
  const matW = SEQ_W;
  const matH = MAT_H;
  const matX = cx - matW / 2;
  const matY = cy - matH / 2;

  drawMatrixBlock(g as Sel, matX, matY, {
    width: matW,
    height: matH,
    label,
    sublabel,
    fill,
    stroke,
    cols: transpose ? 5 : 4,
    rows: transpose ? 4 : 5,
    dimTop: transpose ? 'S' : 'E',
    dimRight: transpose ? 'E' : 'S',
  });

  const cols = transpose ? 5 : 4;
  const rows = transpose ? 4 : 5;
  const cellW = matW / cols;
  const cellH = matH / rows;
  const pad = 2;

  for (let r = 0; r < rows; r++) {
    for (let k = 0; k < selectedPerRow; k++) {
      const c = transpose ? ((r + k * 2 + 1) % cols) : ((r + k * 2 + 1) % cols);
      g.append('rect')
        .attr('x', matX + c * cellW + pad)
        .attr('y', matY + r * cellH + pad)
        .attr('width', cellW - pad * 2)
        .attr('height', cellH - pad * 2)
        .attr('rx', 2)
        .attr('fill', stroke)
        .attr('opacity', 0.28)
        .attr('stroke', stroke)
        .attr('stroke-width', 1.2);
    }
  }

  return cy + MAT_H / 2 + ROW_EQ_GAP + 10;
}

function drawSmallIndexWeightVectors(
  g: Gsel,
  cx: number,
  cy: number,
  topK: number,
  variant: 'token' | 'expert'
): number {
  const leftX = cx - 166;
  const rightX = cx + 6;
  const shape = variant === 'token' ? '[B, S, K]' : '[E, K]';

  drawSmallVector(g, leftX, cy, 'indices', shape, COLORS.topk.fill, COLORS.topk.stroke);
  drawSmallVector(g, rightX, cy, 'weights', shape, COLORS.softmax.fill, COLORS.softmax.stroke);

  lbl(g, cx, cy + 32, `top-${topK} ${variant === 'token' ? 'experts per token' : 'tokens per expert'}`, {
    size: 12,
    color: COLORS.muted,
    font: 'monospace',
  });
  return cy + 56;
}

function drawExpertBoxes(g: Gsel, cx: number, y: number, nExperts: number, expertType: string): number {
  const shownExperts = Math.min(nExperts, 4);
  const totalW = shownExperts * EXPERT_BOX_W + (shownExperts - 1) * EXPERT_GAP;
  const startX = cx - totalW / 2;

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (EXPERT_BOX_W + EXPERT_GAP);
    const eg = g.append('g');
    eg.append('rect')
      .attr('x', x).attr('y', y)
      .attr('width', EXPERT_BOX_W).attr('height', EXPERT_BOX_H).attr('rx', 8)
      .attr('fill', COLORS.expert.fill).attr('stroke', COLORS.expert.stroke).attr('stroke-width', 1.5);
    eg.append('rect')
      .attr('x', x + 12).attr('y', y + 34)
      .attr('width', EXPERT_BOX_W - 24).attr('height', 28).attr('rx', 5)
      .attr('fill', '#fff').attr('stroke', COLORS.expert.stroke).attr('stroke-width', 1);
    lbl(eg, x + EXPERT_BOX_W / 2, y + 20, `Expert ${i + 1}`, { size: 13, weight: '600', color: COLORS.expert.stroke });
    const typeLabel = expertType === 'swiglu' ? 'SwiGLU [D→d→D]' : 'FFN [D→d→D]';
    lbl(eg, x + EXPERT_BOX_W / 2, y + 50, typeLabel, { size: 9, color: COLORS.muted, font: 'monospace' });
  }

  if (nExperts > shownExperts) {
    lbl(g, cx, y + EXPERT_BOX_H + 22, `… + ${nExperts - shownExperts} more experts`, { size: 11, color: COLORS.muted });
    return y + EXPERT_BOX_H + 44;
  }
  return y + EXPERT_BOX_H + 22;
}

function drawDispatchArrows(g: Gsel, cx: number, fromY: number, toY: number, nExperts: number): void {
  const shownExperts = Math.min(nExperts, 4);
  const totalW = shownExperts * EXPERT_BOX_W + (shownExperts - 1) * EXPERT_GAP;
  const startX = cx - totalW / 2;

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (EXPERT_BOX_W + EXPERT_GAP) + EXPERT_BOX_W / 2;
    drawArrow(g as Sel, cx, fromY, x, toY, { color: COLORS.dispatch.stroke });
  }
}

function drawExpertInternalFlow(
  g: Gsel,
  cx: number,
  cy: number,
  expertType: string
): number {
  if (expertType === 'swiglu') {
    return drawSwigluFlow(g, cx, cy);
  }
  return drawStandardFfnFlow(g, cx, cy);
}

function drawStandardFfnFlow(g: Gsel, cx: number, cy: number): number {
  // Snake-style vertical FFN pipeline.  Each stage is a horizontal row; data
  // flows right on the first row, left on the activation row, and right again
  // on the down-projection row.  Operator circles sit in the gap between the
  // weight matrix and the output vector so nothing overlaps.
  const vecW = 120;
  const inputX = cx - 220;   // left edge of input vector
  const weightX = cx - 40;   // left edge of weight matrix
  const opX = cx + 130;      // matmul circle
  const outX = cx + 160;     // left edge of output vector
  const rowGap = 64;

  // Stage 1: x̂ @ W_up → h
  drawSmallVector(g, inputX, cy, 'x̂', '[B, S, D]', COLORS.norm.fill, COLORS.norm.stroke, vecW);
  drawWeightMatrix(g, weightX, cy, 'W_up', '[D, d_ff]', COLORS.weight.fill, COLORS.weight.stroke);
  drawSmallVector(g, outX, cy, 'h', '[B, S, d_ff]', COLORS.expert.fill, COLORS.expert.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, cy, '@', { size: 13, weight: '700', color: '#64748b' });
  arrowH(g, inputX + vecW, opX - 14, cy, COLORS.norm.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, cy, COLORS.weight.stroke);
  arrowH(g, opX + 14, outX, cy, COLORS.expert.stroke);
  drawShapeEquation(g, cx, cy, '[B, S, D] @ [D, d_ff] → [B, S, d_ff]');

  // Stage 2: h → activation → a
  const actCy = cy + VEC_H / 2 + rowGap;
  const badgeW = 110;
  const badgeX = cx - badgeW / 2;   // activation badge centred
  drawSmallVector(g, outX, actCy, 'h', '[B, S, d_ff]', COLORS.expert.fill, COLORS.expert.stroke, vecW);
  g.append('rect')
    .attr('x', badgeX).attr('y', actCy - VEC_H / 2)
    .attr('width', badgeW).attr('height', VEC_H).attr('rx', 6)
    .attr('fill', COLORS.activation.fill).attr('stroke', COLORS.activation.stroke).attr('stroke-width', 1.5);
  lbl(g, cx, actCy, 'activation', { size: 11, weight: '600', color: COLORS.activation.stroke });
  drawSmallVector(g, inputX, actCy, 'a', '[B, S, d_ff]', COLORS.activation.fill, COLORS.activation.stroke, vecW);
  arrowH(g, outX, badgeX + badgeW, actCy, COLORS.expert.stroke);
  arrowH(g, badgeX, inputX + vecW, actCy, COLORS.activation.stroke);
  lbl(g, cx, actCy + VEC_H / 2 + 20, 'e.g. GELU / ReLU / Swish', { size: 11, color: COLORS.muted });

  // Stage 3: a @ W_down → out
  const downCy = actCy + VEC_H / 2 + rowGap;
  drawSmallVector(g, inputX, downCy, 'a', '[B, S, d_ff]', COLORS.activation.fill, COLORS.activation.stroke, vecW);
  drawWeightMatrix(g, weightX, downCy, 'W_down', '[d_ff, D]', COLORS.down.fill, COLORS.down.stroke);
  drawSmallVector(g, outX, downCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', downCy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, downCy, '@', { size: 13, weight: '700', color: '#64748b' });
  arrowH(g, inputX + vecW, opX - 14, downCy, COLORS.activation.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, downCy, COLORS.down.stroke);
  arrowH(g, opX + 14, outX, downCy, COLORS.output.stroke);
  drawShapeEquation(g, cx, downCy, '[B, S, d_ff] @ [d_ff, D] → [B, S, D]');

  return downCy + MAT_H / 2 + ROW_EQ_GAP + 12;
}

function drawSwigluFlow(g: Gsel, cx: number, cy: number): number {
  // Vertical SwiGLU pipeline: gate and up projections stacked vertically, both
  // fed from the shared x̂ at the top; gate is activated, then multiplied with
  // up, finally down-projected.  Operator circles sit in the gap between the
  // weight matrix and the output vector; the multiply output is placed to the
  // right of the circle so it does not overlap.
  const vecW = 120;
  const inputX = cx - 220;
  const weightX = cx - 40;
  const opX = cx + 130;
  const outX = cx + 160;
  const rowGap = 64;

  // Row 0: shared input x̂
  const inputCy = cy - 64;
  drawSmallVector(g, inputX, inputCy, 'x̂', '[B, S, D]', COLORS.norm.fill, COLORS.norm.stroke, vecW);

  // Row 1: x̂ @ W_gate → gate
  const gateCy = cy + 28;
  drawSmallVector(g, inputX, gateCy, 'x̂', '[B, S, D]', COLORS.norm.fill, COLORS.norm.stroke, vecW);
  drawWeightMatrix(g, weightX, gateCy, 'W_gate', '[D, d_ff]', COLORS.gate.fill, COLORS.gate.stroke);
  drawSmallVector(g, outX, gateCy, 'gate', '[B, S, d_ff]', COLORS.gate.fill, COLORS.gate.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', gateCy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, gateCy, '@', { size: 13, weight: '700', color: '#64748b' });
  arrowDown(g, cx, inputCy + VEC_H / 2, gateCy - 14, COLORS.norm.stroke);
  arrowH(g, inputX + vecW, opX - 14, gateCy, COLORS.norm.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, gateCy, COLORS.gate.stroke);
  arrowH(g, opX + 14, outX, gateCy, COLORS.gate.stroke);
  drawShapeEquation(g, cx, gateCy, '[B, S, D] @ [D, d_ff] → [B, S, d_ff]');

  // Row 2: gate → SiLU(gate)
  const siluCy = gateCy + VEC_H / 2 + rowGap;
  const siluBadgeW = 70;
  const siluBadgeX = outX - siluBadgeW - 18;
  drawSmallVector(g, outX, siluCy, 'SiLU(gate)', '[B, S, d_ff]', COLORS.activation.fill, COLORS.activation.stroke, vecW);
  g.append('rect')
    .attr('x', siluBadgeX).attr('y', siluCy - VEC_H / 2)
    .attr('width', siluBadgeW).attr('height', VEC_H).attr('rx', 6)
    .attr('fill', COLORS.activation.fill).attr('stroke', COLORS.activation.stroke).attr('stroke-width', 1.5);
  lbl(g, siluBadgeX + siluBadgeW / 2, siluCy, 'SiLU', { size: 10, weight: '600', color: COLORS.activation.stroke });
  arrowDown(g, outX, gateCy + VEC_H / 2, siluCy - VEC_H / 2, COLORS.gate.stroke);
  arrowH(g, outX, siluBadgeX + siluBadgeW, siluCy, COLORS.gate.stroke);
  lbl(g, cx, siluCy + VEC_H / 2 + 20, 'SiLU activation on gate', { size: 11, color: COLORS.muted });

  // Row 3: x̂ @ W_up → up
  const upCy = siluCy + VEC_H / 2 + rowGap;
  drawSmallVector(g, inputX, upCy, 'x̂', '[B, S, D]', COLORS.norm.fill, COLORS.norm.stroke, vecW);
  drawWeightMatrix(g, weightX, upCy, 'W_up', '[D, d_ff]', COLORS.up.fill, COLORS.up.stroke);
  drawSmallVector(g, outX, upCy, 'up', '[B, S, d_ff]', COLORS.up.fill, COLORS.up.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', upCy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, upCy, '@', { size: 13, weight: '700', color: '#64748b' });
  drawArrow(g as Sel, cx, inputCy + VEC_H / 2, opX, upCy - 14, { color: COLORS.norm.stroke });
  arrowH(g, inputX + vecW, opX - 14, upCy, COLORS.norm.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, upCy, COLORS.up.stroke);
  arrowH(g, opX + 14, outX, upCy, COLORS.up.stroke);
  drawShapeEquation(g, cx, upCy, '[B, S, D] @ [D, d_ff] → [B, S, d_ff]');

  // Row 4: SiLU(gate) ⊗ up → gated
  const mulCy = upCy + VEC_H / 2 + rowGap;
  const gatedX = cx + 36;
  g.append('circle').attr('cx', cx).attr('cy', mulCy).attr('r', 22)
    .attr('fill', '#fff').attr('stroke', COLORS.mul.stroke).attr('stroke-width', 2);
  lbl(g, cx, mulCy, '⊗', { size: 18, weight: '700', color: COLORS.mul.stroke });
  drawSmallVector(g, gatedX, mulCy, 'gated', '[B, S, d_ff]', COLORS.mul.fill, COLORS.mul.stroke, vecW);
  drawArrow(g as Sel, outX, siluCy + VEC_H / 2, cx - 14, mulCy - 14, { color: COLORS.activation.stroke });
  drawArrow(g as Sel, outX, upCy + VEC_H / 2, cx + 14, mulCy - 14, { color: COLORS.up.stroke });
  arrowH(g, cx + 22, gatedX, mulCy, COLORS.mul.stroke);
  lbl(g, cx, mulCy + VEC_H / 2 + 20, 'element-wise multiply', { size: 11, color: COLORS.muted });

  // Row 5: gated @ W_down → out
  const downCy = mulCy + VEC_H / 2 + rowGap;
  drawSmallVector(g, inputX, downCy, 'gated', '[B, S, d_ff]', COLORS.mul.fill, COLORS.mul.stroke, vecW);
  drawWeightMatrix(g, weightX, downCy, 'W_down', '[d_ff, D]', COLORS.down.fill, COLORS.down.stroke);
  drawSmallVector(g, outX, downCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', downCy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, downCy, '@', { size: 13, weight: '700', color: '#64748b' });
  arrowDown(g, gatedX + vecW / 2, mulCy + VEC_H / 2, downCy - 14, COLORS.mul.stroke);
  arrowH(g, inputX + vecW, opX - 14, downCy, COLORS.mul.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, downCy, COLORS.down.stroke);
  arrowH(g, opX + 14, outX, downCy, COLORS.output.stroke);
  drawShapeEquation(g, cx, downCy, '[B, S, d_ff] @ [d_ff, D] → [B, S, D]');

  return downCy + MAT_H / 2 + ROW_EQ_GAP + 12;
}

function drawSharedExpertBox(g: Gsel, cx: number, cy: number, expertType: string): number {
  const boxW = 220;
  const boxH = 80;
  const x = cx - boxW / 2;
  const y = cy - boxH / 2;

  g.append('rect')
    .attr('x', x).attr('y', y)
    .attr('width', boxW).attr('height', boxH).attr('rx', 10)
    .attr('fill', COLORS.shared.fill).attr('stroke', COLORS.shared.stroke).attr('stroke-width', 2);
  g.append('rect')
    .attr('x', x + 14).attr('y', y + 36)
    .attr('width', boxW - 28).attr('height', 30).attr('rx', 6)
    .attr('fill', '#fff').attr('stroke', COLORS.shared.stroke).attr('stroke-width', 1);
  lbl(g, cx, y + 24, 'Shared Expert', { size: 14, weight: '600', color: COLORS.shared.stroke });
  const typeLabel = expertType === 'swiglu' ? 'SwiGLU  [B, S, D] → [B, S, D]' : 'FFN  [B, S, D] → [B, S, D]';
  lbl(g, cx, y + 54, typeLabel, { size: 10, color: COLORS.muted, font: 'monospace' });

  return cy + boxH / 2 + 18;
}

function drawCombineRow(g: Gsel, cx: number, cy: number, nExperts: number, topK: number, hasShared: boolean, expertType: string, routing: string): number {
  const shownExperts = Math.min(nExperts, 4);
  const totalW = shownExperts * EXPERT_BOX_W + (shownExperts - 1) * EXPERT_GAP;
  const startX = cx - totalW / 2;
  const outVecW = 100;

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (EXPERT_BOX_W + EXPERT_GAP);
    drawSmallVector(g, x + (EXPERT_BOX_W - outVecW) / 2, cy, `out_${i + 1}`, '[B, S, D]', COLORS.expert.fill, COLORS.expert.stroke, outVecW);
  }

  const circleCy = cy + VEC_H / 2 + 42;
  g.append('circle').attr('cx', cx).attr('cy', circleCy).attr('r', 20)
    .attr('fill', '#fff').attr('stroke', COLORS.combine.stroke).attr('stroke-width', 2);
  lbl(g, cx, circleCy, 'Σ', { size: 16, weight: '700', color: COLORS.combine.stroke });

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (EXPERT_BOX_W + EXPERT_GAP) + EXPERT_BOX_W / 2;
    drawArrow(g as Sel, x, cy + VEC_H / 2, cx, circleCy - 20, { color: COLORS.expert.stroke });
  }

  let currentY = circleCy;

  if (hasShared) {
    const plusY = circleCy + 62;
    const sharedCy = plusY + 70;
    g.append('circle').attr('cx', cx).attr('cy', plusY).attr('r', 16)
      .attr('fill', '#fff').attr('stroke', COLORS.shared.stroke).attr('stroke-width', 2);
    lbl(g, cx, plusY, '+', { size: 16, weight: '700', color: COLORS.shared.stroke });
    drawSharedExpertBox(g, cx, sharedCy, expertType);
    arrowDown(g, cx, circleCy + 20, plusY - 16, COLORS.combine.stroke);
    arrowDown(g, cx, plusY + 16, sharedCy - 40, COLORS.shared.stroke);
    currentY = sharedCy + 40;
  }

  const outCy = currentY + 62;
  drawSeqMatrix(g, cx - 80, outCy, 'moe_out', '[B, S, D]', COLORS.combine.fill, COLORS.combine.stroke);
  arrowDown(g, cx, currentY + 20, outCy - MAT_H / 2, COLORS.combine.stroke);

  let note: string;
  if (topK === 1) {
    note = 'single expert output';
  } else if (routing === 'expert-choice') {
    note = 'weighted sum of active expert outputs per token';
  } else {
    note = `weighted sum over top-${topK} experts`;
  }
  const fullNote = hasShared ? `${note} + shared expert` : note;
  lbl(g, cx, outCy + MAT_H / 2 + 20, fullNote, { size: 12, color: COLORS.muted });
  return outCy + MAT_H / 2 + 40;
}

function drawResidualAdd(g: Gsel, cx: number, cy: number): number {
  const inputX = cx - 160;
  const moeX = cx - 20;
  const plusX = cx + 60;
  const outX = cx + 140;

  drawSmallVector(g, inputX, cy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  drawSmallVector(g, moeX, cy, 'moe_out', '[B, S, D]', COLORS.combine.fill, COLORS.combine.stroke);

  g.append('circle').attr('cx', plusX).attr('cy', cy).attr('r', 18)
    .attr('fill', '#fff').attr('stroke', COLORS.residual.stroke).attr('stroke-width', 2);
  lbl(g, plusX, cy, '+', { size: 18, weight: '700', color: COLORS.residual.stroke });

  arrowH(g, inputX + VEC_W, plusX - 18, cy, COLORS.input.stroke);
  arrowH(g, moeX + VEC_W, plusX - 18, cy, COLORS.combine.stroke);

  drawSmallVector(g, outX, cy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  arrowH(g, plusX + 18, outX, cy, COLORS.residual.stroke);
  lbl(g, cx + 20, cy + 34, 'residual add', { size: 12, color: COLORS.muted });

  return cy + VEC_H / 2 + 36;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderLeftColumn(
  _g: Gsel,
  yL: number,
  topK: number,
  routing: string
): { yL: number; steps: MoeLayerStep[] } {
  const steps: MoeLayerStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inHeaderBottom = stepHeader(inputGrp, CX_L, yL, 1, 'Input hidden states', 'x ∈ ℝ^(B×S×D)', COLORS.input.fill, COLORS.input.stroke);
  const inCy = inHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(inputGrp, CX_L - 80, inCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(inputGrp, CX_L, inCy + MAT_H / 2 + 18, 'each row = one token embedding', { size: 12, color: COLORS.muted });
  yL = inCy + MAT_H / 2 + 28;

  // 2. Norm
  steps.push({ ...BASE_STEPS.norm, id: 2 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.norm.stroke);
  yL += GROUP_GAP;
  const normGrp = startGroup(_g, STEP_GROUPS.norm, 2);
  const normHeaderBottom = stepHeader(normGrp, CX_L, yL, 2, 'Pre-normalization', 'x̂ = LayerNorm(x)', COLORS.norm.fill, COLORS.norm.stroke);
  const normCy = normHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(normGrp, CX_L - 80, normCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  arrowDown(normGrp, CX_L, normCy + VEC_H / 2, normCy + VEC_H / 2 + 24, COLORS.norm.stroke);
  drawSmallVector(normGrp, CX_L - 80, normCy + VEC_H / 2 + 24 + VEC_H / 2, 'x̂', '[B, S, D]', COLORS.norm.fill, COLORS.norm.stroke);
  lbl(normGrp, CX_L, normCy + VEC_H / 2 + 24 + VEC_H + 14, 'μ, σ normalization + γ, β scale/shift', { size: 11, color: COLORS.muted });
  yL = normCy + VEC_H / 2 + 24 + VEC_H + 24;

  // 3. Gate projection
  steps.push({ ...BASE_STEPS.gate, id: 3 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.gate.stroke);
  yL += GROUP_GAP;
  const gateGrp = startGroup(_g, STEP_GROUPS.gate, 3);
  const gateHeaderBottom = stepHeader(gateGrp, CX_L, yL, 3, 'Router gate projection', 'logits = x̂ · W_gate', COLORS.gate.fill, COLORS.gate.stroke);
  const gateRowCy = gateHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const gateBottom = drawMatmulRow(
    gateGrp, CX_L, gateRowCy,
    'x̂', '[B, S, D]', COLORS.norm.fill, COLORS.norm.stroke,
    'W_gate', '[D, E]', COLORS.weight.fill, COLORS.weight.stroke,
    'logits', '[B, S, E]', COLORS.gate.fill, COLORS.gate.stroke,
    '[B, S, D] @ [D, E] → [B, S, E]'
  );
  yL = gateBottom + GROUP_GAP;

  // 4. Softmax
  const softmaxFormula = routing === 'expert-choice' ? 'probs = softmax(logits, dim=1)' : 'probs = softmax(logits, dim=-1)';
  const softmaxLabel = routing === 'expert-choice' ? 'Softmax over tokens' : 'Softmax over experts';
  steps.push({
    ...BASE_STEPS.softmax,
    id: 4,
    label: softmaxLabel,
    formula: softmaxFormula,
    explanation: routing === 'expert-choice'
      ? 'Each expert normalizes its preference over all tokens in the sequence.'
      : 'Scores are normalized into a probability distribution over experts.',
    code: {
      title: 'Softmax',
      lines: [routing === 'expert-choice' ? 'probs = F.softmax(logits, dim=1)  # [B, S, E]' : 'probs = F.softmax(logits, dim=-1)  # [B, S, E]'],
    },
  });
  arrowDown(_g, CX_L, yL - GROUP_GAP, yL, COLORS.softmax.stroke);
  const softmaxGrp = startGroup(_g, STEP_GROUPS.softmax, 4);
  const softmaxHeaderBottom = stepHeader(softmaxGrp, CX_L, yL, 4, softmaxLabel, softmaxFormula, COLORS.softmax.fill, COLORS.softmax.stroke);
  const softmaxVecCy = softmaxHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(softmaxGrp, CX_L - 80, softmaxVecCy, 'logits', '[B, S, E]', COLORS.gate.fill, COLORS.gate.stroke);
  arrowDown(softmaxGrp, CX_L, softmaxVecCy + VEC_H / 2, softmaxVecCy + VEC_H / 2 + 24, COLORS.softmax.stroke);
  const softmaxMatCy = softmaxVecCy + VEC_H / 2 + 24 + MAT_H / 2;
  drawScoreMatrix(softmaxGrp, CX_L - 80, softmaxMatCy, 'probs', '[B, S, E]', COLORS.softmax.fill, COLORS.softmax.stroke);
  const sumNote = routing === 'expert-choice' ? 'each column sums to 1.0 across tokens' : 'each row sums to 1.0 across experts';
  lbl(softmaxGrp, CX_L, softmaxMatCy + MAT_H / 2 + 18, sumNote, { size: 11, color: COLORS.muted });
  yL = softmaxMatCy + MAT_H / 2 + 28;

  // 5. Top-k
  const topkLabel = routing === 'switch' ? 'Top-1 selection' : routing === 'expert-choice' ? 'Top-k tokens per expert' : 'Top-k expert selection';
  const topkFormula = routing === 'switch' ? 'index = argmax(probs)' : routing === 'expert-choice' ? 'weights, indices = topk(probs^T, k)' : 'weights, indices = topk(probs, k)';
  const topkShort = routing === 'switch' ? 'Top-1' : 'Top-k';
  steps.push({
    ...BASE_STEPS.topk,
    id: 5,
    label: topkLabel,
    shortLabel: topkShort,
    formula: topkFormula,
    explanation: routing === 'switch'
      ? 'Switch routing assigns each token to exactly one expert (top-1).'
      : routing === 'expert-choice'
        ? 'Each expert selects its top-k tokens instead of each token selecting experts.'
        : 'Each token selects its top-k experts and their corresponding weights.',
    code: {
      title: topkShort,
      lines: routing === 'switch'
        ? ['index = probs.argmax(dim=-1)  # [B, S]']
        : routing === 'expert-choice'
          ? [`weights, indices = probs.transpose(1,2).topk(${topK}, dim=-1)  # [B, E, ${topK}]`]
          : [`weights, indices = probs.topk(${topK}, dim=-1)  # [B, S, ${topK}]`],
    },
  });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.topk.stroke);
  yL += GROUP_GAP;
  const topkGrp = startGroup(_g, STEP_GROUPS.topk, 5);
  const topkHeaderBottom = stepHeader(topkGrp, CX_L, yL, 5, topkLabel, topkFormula, COLORS.topk.fill, COLORS.topk.stroke);
  const topkMatCy = topkHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;

  if (routing === 'switch') {
    drawTopKMatrix(topkGrp, CX_L, topkMatCy, 'probs', '[B, S, E]', COLORS.softmax.fill, COLORS.softmax.stroke, 1, false);
    const vecCy = topkMatCy + MAT_H / 2 + ROW_EQ_GAP + 18;
    drawSmallVector(topkGrp, CX_L - 80, vecCy, 'index', '[B, S]', COLORS.topk.fill, COLORS.topk.stroke);
    lbl(topkGrp, CX_L, vecCy + 32, 'one expert per token', { size: 12, color: COLORS.muted, font: 'monospace' });
    yL = vecCy + 48 + GROUP_GAP;
  } else if (routing === 'expert-choice') {
    drawTopKMatrix(topkGrp, CX_L, topkMatCy, 'probs^T', '[E, S]', COLORS.softmax.fill, COLORS.softmax.stroke, topK, true);
    const vecCy = topkMatCy + MAT_H / 2 + ROW_EQ_GAP + 18;
    drawSmallIndexWeightVectors(topkGrp, CX_L, vecCy, topK, 'expert');
    yL = vecCy + 56 + GROUP_GAP;
  } else {
    drawTopKMatrix(topkGrp, CX_L, topkMatCy, 'probs', '[B, S, E]', COLORS.softmax.fill, COLORS.softmax.stroke, topK, false);
    const vecCy = topkMatCy + MAT_H / 2 + ROW_EQ_GAP + 18;
    drawSmallIndexWeightVectors(topkGrp, CX_L, vecCy, topK, 'token');
    yL = vecCy + 56 + GROUP_GAP;
  }

  return { yL, steps };
}

function renderRightColumn(
  _g: Gsel,
  yR: number,
  nExperts: number,
  topK: number,
  sharedExperts: number,
  expertType: string,
  routing: string
): { yR: number; steps: MoeLayerStep[] } {
  const steps: MoeLayerStep[] = [];

  // 6. Dispatch
  const dispatchLabel = routing === 'expert-choice' ? 'Dispatch selected tokens' : routing === 'switch' ? 'Dispatch to one expert' : 'Dispatch to selected experts';
  const dispatchFormula = routing === 'expert-choice' ? 'experts → top-k tokens' : routing === 'switch' ? 'tokens → single expert' : 'tokens → top-k experts';
  steps.push({
    ...BASE_STEPS.dispatch,
    id: 6,
    label: dispatchLabel,
    formula: dispatchFormula,
    explanation: routing === 'expert-choice'
      ? 'Each expert receives only its selected top-k tokens.'
      : routing === 'switch'
        ? 'Each token is routed to its single selected expert.'
        : 'Each token is sent to the experts it selected.',
    code: {
      title: 'Dispatch',
      lines: routing === 'expert-choice'
        ? ['for each expert e and selected token s:', '    dispatch x̂[s] to expert_e']
        : routing === 'switch'
          ? ['for each token s:', '    dispatch x̂[s] to expert_index[s]']
          : ['for each token s and selected expert e:', '    dispatch x̂[s] to expert_e'],
    },
  });
  const dispatchGrp = startGroup(_g, STEP_GROUPS.dispatch, 6);
  const dispatchHeaderBottom = stepHeader(dispatchGrp, CX_R, yR, 6, dispatchLabel, dispatchFormula, COLORS.dispatch.fill, COLORS.dispatch.stroke);
  const expertY = dispatchHeaderBottom + HEADER_TO_ROW_GAP + 22;
  drawDispatchArrows(dispatchGrp, CX_R, dispatchHeaderBottom + HEADER_TO_ROW_GAP, expertY, nExperts);
  const expertBottom = drawExpertBoxes(dispatchGrp, CX_R, expertY, nExperts, expertType);
  yR = expertBottom + GROUP_GAP;

  // 7. Expert computation
  steps.push({
    ...BASE_STEPS.expert,
    id: 7,
    formula: expertType === 'swiglu' ? 'E_i(x̂) = SwiGLU(x̂)' : 'E_i(x̂) = FFN(x̂)',
    code: {
      title: expertType === 'swiglu' ? 'SwiGLU Expert' : 'Standard FFN Expert',
      lines: expertType === 'swiglu'
        ? [
            'gate = SiLU(x̂ @ W_gate)',
            'up   = x̂ @ W_up',
            'gated = gate * up',
            'out  = gated @ W_down',
          ]
        : [
            'h    = x̂ @ W_up',
            'a    = activation(h)',
            'out  = a @ W_down',
          ],
    },
  });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.expert.stroke);
  const expertGrp = startGroup(_g, STEP_GROUPS.expert, 7);
  const expertHeaderBottom = stepHeader(expertGrp, CX_R, yR, 7, 'Expert computation', steps[steps.length - 1].formula, COLORS.expert.fill, COLORS.expert.stroke);
  const expertFlowCy = expertHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const expertBottomY = drawExpertInternalFlow(expertGrp, CX_R, expertFlowCy, expertType);
  yR = expertBottomY + GROUP_GAP;

  // 8. Combine (shared expert is included inside the combine row when enabled)
  steps.push({
    ...BASE_STEPS.combine,
    id: 8,
    formula: sharedExperts > 0 ? 'moe_out = Σ weights·expert_out + shared' : 'moe_out = Σ weights · expert_out',
    code: {
      title: 'Combine',
      lines: sharedExperts > 0
        ? ['moe_out = Σ_k weights[..., k] * expert_outputs[..., k] + shared  # [B, S, D]']
        : ['moe_out = Σ_k weights[..., k] * expert_outputs[..., k]  # [B, S, D]'],
    },
  });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.combine.stroke);
  const combineGrp = startGroup(_g, STEP_GROUPS.combine, 8);
  const combineHeaderBottom = stepHeader(combineGrp, CX_R, yR, 8, 'Weighted combination', steps[steps.length - 1].formula, COLORS.combine.fill, COLORS.combine.stroke);
  const combineCy = combineHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const combineBottom = drawCombineRow(combineGrp, CX_R, combineCy, nExperts, topK, sharedExperts > 0, expertType, routing);
  yR = combineBottom + GROUP_GAP;

  // 9. Residual add
  steps.push({ ...BASE_STEPS.residual, id: 9 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.residual.stroke);
  const residualGrp = startGroup(_g, STEP_GROUPS.residual, 9);
  const residualHeaderBottom = stepHeader(residualGrp, CX_R, yR, 9, 'Residual connection', 'out = x + moe_out', COLORS.residual.fill, COLORS.residual.stroke);
  const residualCy = residualHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const residualBottom = drawResidualAdd(residualGrp, CX_R, residualCy);
  yR = residualBottom + GROUP_GAP;

  // 10. Output
  steps.push({ ...BASE_STEPS.output, id: 10 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 10);
  const outHeaderBottom = stepHeader(outGrp, CX_R, yR, 10, 'Output hidden states', 'out ∈ ℝ^(B×S×D)', COLORS.output.fill, COLORS.output.stroke);
  const outCy = outHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(outGrp, CX_R - 80, outCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  yR = outCy + MAT_H / 2 + GROUP_GAP;

  return { yR, steps };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderMoeLayerDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: import('../../components/types').ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const dFf = Number(params.d_ff) || 2048;
  const seqLen = Number(params.seq_len) || 128;
  const nExperts = Number(params.n_experts) || 4;
  const topK = Number(params.top_k) || 2;
  const sharedExperts = Number(params.shared_experts) || 0;
  const routing = String(params.routing || 'token-choice');
  const expertType = String(params.expert_type || 'standard-ffn');

  const root = g as unknown as Gsel;
  let y = 30;

  // Title
  lbl(root, CX, y, 'MoE Layer', { size: 20, weight: '700', color: COLORS.text });
  y += 24;
  lbl(root, CX, y, `${routing.replace(/-/g, ' ')} · ${expertType.replace(/-/g, ' ')} · d_model=${dModel} · d_ff=${dFf} · seq_len=${seqLen} · n_experts=${nExperts} · top_k=${topK}${sharedExperts > 0 ? ` · shared=${sharedExperts}` : ''}`, {
    size: 12,
    color: COLORS.muted,
  });
  y += 30;

  // Param summary
  y = drawParamSummary(root, CX, y, dModel, dFf, nExperts, topK, sharedExperts, routing, expertType);
  y += 22;

  const columnTop = y;

  // Left column: routing score computation
  const leftResult = renderLeftColumn(root, columnTop, topK, routing);

  // Right column: dispatch, experts, combine, residual, output
  const rightResult = renderRightColumn(root, columnTop, nExperts, topK, sharedExperts, expertType, routing);

  // Combine steps from both columns
  const steps = [...leftResult.steps, ...rightResult.steps].sort((a, b) => a.id - b.id);

  // Continue footer from the taller column
  let footerY = Math.max(leftResult.yL, rightResult.yR) + 20;

  // Footer summary
  const gateParams = dModel * nExperts;
  const expertParams = nExperts * (expertType === 'swiglu' ? 3 : 2) * dModel * dFf;
  const sharedParams = sharedExperts > 0 ? (expertType === 'swiglu' ? 3 : 2) * dModel * dFf : 0;
  const totalParams = gateParams + expertParams + sharedParams;
  const summaryGrp = root.append('g');
  lbl(summaryGrp, CX, footerY + 18, `Params: gate ${fmtNum(gateParams)} + experts ${fmtNum(expertParams)}${sharedExperts > 0 ? ` + shared ${fmtNum(sharedParams)}` : ''} = ${fmtNum(totalParams)}`, {
    size: 11,
    color: COLORS.muted,
  });
  footerY += 38;

  // Side-by-side explanations
  const insightW = (W - 200) / 2;
  const expertText = expertType === 'swiglu'
    ? 'SwiGLU experts use a gated branch (SiLU gate × up-projection) for richer feature mixing than standard FFN. '
    : 'Standard FFN experts expand to d_ff, apply a non-linearity, then project back to d_model. ';
  const routingText = routing === 'expert-choice'
    ? 'Expert-choice routing lets each expert pick its top-k tokens, capping per-expert capacity. '
    : routing === 'switch'
      ? 'Switch routing assigns exactly one expert per token, maximizing sparsity. '
      : 'Token-choice routing lets each token activate only top-k experts. ';
  const insightY = drawExplanation(g, 80, footerY, insightW - 20,
    expertText +
    routingText +
    (sharedExperts > 0 ? 'Shared experts always run, providing stable base knowledge.' : ''),
    'insight'
  );
  const perfText = `Active FLOPs ≈ top_k × ${expertType === 'swiglu' ? 6 : 4} × d_model × d_ff per token. ` +
    'Load balancing keeps experts equally utilized. Expert parallelism shards different experts across GPUs.';
  const perfY = drawExplanation(g, 80 + insightW, footerY, insightW - 20, perfText, 'perf');
  footerY = Math.max(insightY, perfY) + 18;

  // Cross-link
  drawComponentLink(g, CX - 90, footerY, 180, 32, 'moe-router', 'View MoE Router ↗', {
    fill: '#ede9fe',
    stroke: '#7c3aed',
  });
  footerY += 50;

  // Code annotation
  const codeLines = buildCodeLines(routing, expertType, sharedExperts, dModel, dFf, nExperts, topK);
  footerY = drawCodeAnnotation(
    g,
    80,
    footerY,
    W - 160,
    `MoE Layer — ${routing.replace(/-/g, ' ').toUpperCase()} · ${expertType.replace(/-/g, ' ').toUpperCase()}`,
    [`Total params: ${fmtNum(totalParams)}. Active FLOPs per token: ~${fmtNum(topK * (expertType === 'swiglu' ? 6 : 4) * dModel * dFf)}.`],
    codeLines
  );

  return { width: W, height: footerY + 24, steps };
}

function buildCodeLines(
  routing: string,
  expertType: string,
  sharedExperts: number,
  dModel: number,
  dFf: number,
  nExperts: number,
  topK: number
): string[] {
  const lines: string[] = [
    `self.W_gate = nn.Linear(${dModel}, ${nExperts}, bias=False)`,
    expertType === 'swiglu'
      ? `self.experts = nn.ModuleList([SwiGLU(${dModel}, ${dFf}) for _ in range(${nExperts})])`
      : `self.experts = nn.ModuleList([FFN(${dModel}, ${dFf}) for _ in range(${nExperts})])`,
  ];

  if (sharedExperts > 0) {
    lines.push(
      expertType === 'swiglu'
        ? `self.shared = SwiGLU(${dModel}, ${dFf * sharedExperts})`
        : `self.shared = FFN(${dModel}, ${dFf * sharedExperts})`
    );
  }

  lines.push('', 'def forward(self, x):');
  lines.push('    x̂ = self.norm(x)                       # [B, S, D]');
  lines.push('    logits = self.W_gate(x̂)                # [B, S, E]');

  if (routing === 'expert-choice') {
    lines.push('    probs = F.softmax(logits, dim=1)       # [B, S, E]  softmax over sequence');
    lines.push(`    weights, indices = probs.transpose(1,2).topk(${topK}, dim=-1)  # [B, E, ${topK}]`);
  } else if (routing === 'switch') {
    lines.push('    probs = F.softmax(logits, dim=-1)      # [B, S, E]');
    lines.push('    index = probs.argmax(dim=-1)           # [B, S]');
  } else {
    lines.push('    probs = F.softmax(logits, dim=-1)      # [B, S, E]');
    lines.push(`    weights, indices = probs.topk(${topK}, dim=-1)    # [B, S, ${topK}]`);
  }

  lines.push('    # dispatch x̂ to selected experts and compute weighted sum');

  if (sharedExperts > 0) {
    lines.push('    shared = self.shared(x̂)                # [B, S, D]');
    lines.push('    return x + routed_out + shared           # [B, S, D]');
  } else {
    lines.push('    return x + routed_out                    # [B, S, D]');
  }

  return lines;
}
